<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Csrf;use App\Core\Database;use App\Services\SpecialCategoryService;
$pdo=Database::connection();
$token=trim((string)($_GET['token']??''));if($token===''){http_response_code(403);exit('Registration Desk link is missing.');}
$stmt=$pdo->prepare("SELECT l.*,e.name event_name,e.event_date FROM bdc_registration_desk_links l JOIN bdc_events e ON e.id=l.event_id WHERE l.token_hash=:hash AND l.is_enabled=1 AND (l.expires_at IS NULL OR l.expires_at>NOW()) LIMIT 1");$stmt->execute(['hash'=>hash('sha256',$token)]);$desk=$stmt->fetch();if(!$desk){http_response_code(403);exit('This Registration Desk link is invalid, disabled or expired.');}
$requestedRoundId=(int)($_GET['round_id']??0);$roundStmt=$pdo->prepare($requestedRoundId>0?"SELECT * FROM bdc_scoring_rounds WHERE id=:round AND event_id=:event AND division=:division AND status<>'archived' LIMIT 1":"SELECT * FROM bdc_scoring_rounds WHERE event_id=:event AND division=:division AND status NOT IN('archived','completed') ORDER BY id DESC LIMIT 1");$params=['event'=>$desk['event_id'],'division'=>$desk['division']];if($requestedRoundId>0)$params['round']=$requestedRoundId;$roundStmt->execute($params);$round=$roundStmt->fetch();if(!$round){http_response_code(404);exit('The selected scoring round is not available for this Registration Desk link.');}$roundId=(int)$round['id'];
$s=$pdo->prepare("SELECT se.id,se.competitor_id,se.dance_role,se.bib_number,se.display_name,se.entry_status,se.desk_checked_in,se.desk_ready,se.desk_updated_at,se.updated_at,c.bdc_id FROM bdc_scoring_entries se LEFT JOIN bdc_competitors c ON c.id=se.competitor_id WHERE se.round_id=:round ORDER BY se.dance_role,se.bib_number IS NULL,se.bib_number,se.display_name");$s->execute(['round'=>$roundId]);$entries=$s->fetchAll();$csrf=Csrf::token();$label=SpecialCategoryService::isSpecial((string)$desk['division'])?SpecialCategoryService::label((string)$desk['division']):ucfirst((string)$desk['division']);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Registration Desk</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f4f6}.desk-head{background:#111827;color:#fff}.card{border-radius:14px}.leader-head{background:#cfe2ff}.follower-head{background:#f8d7da}.entry-ready{background:#d1e7dd}.missing-bib{background:#fff3cd}.matchbox{z-index:50;max-height:240px;overflow:auto}.bib-input{width:95px}.add-panel{border:1px solid #e5e7eb}.role-title{font-size:1.1rem;font-weight:800}.sticky-summary{position:sticky;top:0;z-index:20}@media(max-width:767.98px){.desk-head .container-fluid,main.container-fluid{padding-left:14px!important;padding-right:14px!important}.action-row{flex-direction:column}.action-row .btn{width:100%}}</style></head><body><header class="desk-head py-3"><div class="container-fluid px-4"><h1 class="h4 mb-1">BDC Registration Desk</h1><div><?=e($desk['event_name'])?> · <?=e($label)?> · <?=e(ucfirst($round['round_type']))?></div></div></header><main class="container-fluid px-4 py-3"><div id="notice"></div><div class="card shadow-sm border-0 mb-3 sticky-summary"><div class="card-body d-flex gap-2 flex-wrap align-items-center"><input id="deskSearch" class="form-control" style="max-width:380px" placeholder="Search registered name, BDC ID or bib"><span class="badge text-bg-success">Live</span><span id="summary" class="text-muted"></span><span id="missingSummary" class="badge text-bg-warning ms-auto"></span></div></div><div class="row g-3 mb-3"><div class="col-xl-6"><div class="card shadow-sm add-panel h-100"><div class="card-header leader-head"><span class="role-title">Leaders</span></div><div class="card-body"><div class="text-muted small mb-3">Search BDC first. Bib is optional and can be assigned later.</div><div class="position-relative mb-2"><label class="form-label">Leader competitor</label><input id="leaderSearch" class="form-control" placeholder="Type leader name or BDC ID" autocomplete="off"><div id="leaderMatches" class="list-group position-absolute w-100 shadow matchbox"></div></div><div class="mb-3"><label class="form-label">Bib</label><input id="leaderBib" type="number" min="1" class="form-control" placeholder="Optional"></div><div class="d-flex gap-2 action-row"><button class="btn btn-primary flex-fill add-existing" data-role="leader">Add Existing</button><button class="btn btn-outline-primary flex-fill create-add" data-role="leader">Create Name & Add</button></div></div></div></div><div class="col-xl-6"><div class="card shadow-sm add-panel h-100"><div class="card-header follower-head"><span class="role-title">Followers</span></div><div class="card-body"><div class="text-muted small mb-3">Search BDC first. Bib is optional and can be assigned later.</div><div class="position-relative mb-2"><label class="form-label">Follower competitor</label><input id="followerSearch" class="form-control" placeholder="Type follower name or BDC ID" autocomplete="off"><div id="followerMatches" class="list-group position-absolute w-100 shadow matchbox"></div></div><div class="mb-3"><label class="form-label">Bib</label><input id="followerBib" type="number" min="1" class="form-control" placeholder="Optional"></div><div class="d-flex gap-2 action-row"><button class="btn btn-primary flex-fill add-existing" data-role="follower">Add Existing</button><button class="btn btn-outline-primary flex-fill create-add" data-role="follower">Create Name & Add</button></div></div></div></div></div><div class="row g-3" id="rolePanels"></div></main><script>
const token=<?=json_encode($token)?>,roundId=<?=$roundId?>,csrf=<?=json_encode($csrf)?>;let entries=<?=json_encode($entries,JSON_UNESCAPED_SLASHES)?>;const api='index.php';const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function roleEls(role){return{search:document.getElementById(role+'Search'),bib:document.getElementById(role+'Bib'),matches:document.getElementById(role+'Matches')}}
function notice(text,kind='success'){document.getElementById('notice').innerHTML=`<div class="alert alert-${kind}">${esc(text)}</div>`;setTimeout(()=>{document.getElementById('notice').innerHTML=''},3500)}
function render(){const q=document.getElementById('deskSearch').value.toLowerCase();let missingAll=0,total=0,ready=0;document.getElementById('rolePanels').innerHTML=['leader','follower'].map(role=>{const rows=entries.filter(e=>e.dance_role===role&&e.entry_status==='active'&&(!q||(`${e.display_name} ${e.bdc_id||''} ${e.bib_number||''}`).toLowerCase().includes(q)));const missing=rows.filter(e=>!e.bib_number).length;missingAll+=missing;total+=rows.length;ready+=rows.filter(e=>+e.desk_ready).length;return `<div class="col-xl-6"><div class="card shadow-sm h-100"><div class="card-header ${role==='leader'?'leader-head':'follower-head'}"><strong>${role==='leader'?'Leaders':'Followers'}</strong><span class="float-end badge text-bg-primary">${rows.length} total · ${rows.filter(e=>+e.desk_ready).length} ready · ${missing} missing bib</span></div><div class="card-body p-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th class="ps-3">Bib</th><th>Competitor</th><th>BDC ID</th><th>Check in</th><th>Ready</th><th class="pe-3">Action</th></tr></thead><tbody>${rows.length?rows.map(e=>`<tr class="${+e.desk_ready?'entry-ready':(!e.bib_number?'missing-bib':'')}"><td class="ps-3"><input class="form-control form-control-sm bib-input" type="number" min="1" placeholder="Blank" value="${e.bib_number??''}" data-bib="${e.id}"></td><td><strong>${esc(e.display_name)}</strong></td><td>${esc(e.bdc_id||'')}</td><td><input class="form-check-input" type="checkbox" data-checked="${e.id}" ${+e.desk_checked_in?'checked':''}></td><td><input class="form-check-input" type="checkbox" data-ready="${e.id}" ${+e.desk_ready?'checked':''}></td><td class="pe-3"><button class="btn btn-sm btn-outline-danger" data-remove="${e.id}">Remove</button></td></tr>`).join(''):`<tr><td colspan="6" class="text-center text-muted py-4">No ${role==='leader'?'leaders':'followers'} registered.</td></tr>`}</tbody></table></div></div></div></div>`}).join('');document.getElementById('summary').textContent=`${total} registered · ${ready} ready`;document.getElementById('missingSummary').textContent=`${missingAll} missing bib`;bindRows()}
async function jsonFetch(url,opts={}){const r=await fetch(url,{cache:'no-store',...opts,headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest',...(opts.headers||{})}});const text=await r.text();let j;try{j=JSON.parse(text)}catch{throw new Error('Registration Desk returned an invalid response.');}if(!r.ok||!j.ok)throw new Error(j.error||'Request failed.');return j}
async function search(role){const el=roleEls(role),term=el.search.value.trim();el.matches.innerHTML='';if(term.length<2)return;try{const j=await jsonFetch(`${api}?token=${encodeURIComponent(token)}&round_id=${roundId}&competitor_search=${encodeURIComponent(term)}&role=${role}`);el.matches.innerHTML=j.competitors.map(c=>`<button type="button" class="list-group-item list-group-item-action ${c.eligible?'':'disabled'}" data-pick-role="${role}" data-pick="${esc(c.bdc_id)}" ${c.eligible?'':'disabled'}><strong>${esc(c.name)}</strong><div class="small">${esc(c.bdc_id)}${c.eligible?'':' · '+esc(c.reason||'Not eligible')}</div></button>`).join('');el.matches.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{el.search.value=b.dataset.pick;el.matches.innerHTML=''})}catch(e){notice(e.message,'danger')}}
let timers={};['leader','follower'].forEach(role=>{const el=roleEls(role);el.search.addEventListener('input',()=>{clearTimeout(timers[role]);timers[role]=setTimeout(()=>search(role),250)});el.search.addEventListener('focus',()=>search(role))});document.addEventListener('click',e=>{if(!e.target.closest('.position-relative'))document.querySelectorAll('.matchbox').forEach(x=>x.innerHTML='')});
async function add(role,mode){const el=roleEls(role),term=el.search.value.trim(),bib=el.bib.value.trim();if(!term){notice(`Enter a ${role} name or BDC ID.`,'warning');return}const body=new URLSearchParams({_csrf:csrf,token:token,round_id:String(roundId),action:'add_entry',dance_role:role,competitor_search:term,bib:bib,entry_mode:mode});try{const j=await jsonFetch(api,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()});entries=j.entries;el.search.value='';el.bib.value='';el.matches.innerHTML='';render();notice(mode==='create'?`New ${role} created and added.`:`${role==='leader'?'Leader':'Follower'} added.`)}catch(e){notice(e.message,'danger')}}
document.querySelectorAll('.add-existing').forEach(b=>b.onclick=()=>add(b.dataset.role,'existing'));document.querySelectorAll('.create-add').forEach(b=>b.onclick=()=>add(b.dataset.role,'create'));
async function updateEntry(id){const bib=document.querySelector(`[data-bib="${id}"]`).value.trim(),checked=document.querySelector(`[data-checked="${id}"]`).checked?'1':'0',ready=document.querySelector(`[data-ready="${id}"]`).checked?'1':'0';const body=new URLSearchParams({_csrf:csrf,token:token,round_id:String(roundId),action:'update_entry',entry_id:String(id),bib:bib,checked:checked,ready:ready,status:'active'});try{const j=await jsonFetch(api,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()});entries=j.entries;render()}catch(e){notice(e.message,'danger')}}
async function removeEntry(id){if(!confirm('Remove this competitor from the active registration list?'))return;const body=new URLSearchParams({_csrf:csrf,token:token,round_id:String(roundId),action:'remove_entry',entry_id:String(id)});try{const j=await jsonFetch(api,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()});entries=j.entries;render();notice('Competitor removed.')}catch(e){notice(e.message,'danger')}}
function bindRows(){document.querySelectorAll('[data-bib]').forEach(x=>x.onchange=()=>updateEntry(x.dataset.bib));document.querySelectorAll('[data-checked]').forEach(x=>x.onchange=()=>updateEntry(x.dataset.checked));document.querySelectorAll('[data-ready]').forEach(x=>x.onchange=()=>updateEntry(x.dataset.ready));document.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>removeEntry(x.dataset.remove))}
document.getElementById('deskSearch').addEventListener('input',render);let pollBusy=false;async function poll(){if(document.hidden||pollBusy)return;pollBusy=true;try{const j=await jsonFetch(`${api}?token=${encodeURIComponent(token)}&round_id=${roundId}&live=1`);entries=j.entries;render()}catch(e){}finally{pollBusy=false}}render();setInterval(poll,10000);
</script></body></html>
